#!/usr/bin/env python3
"""Writes schools.json, lineages.json, practices.json, texts.json and the *-additions files for the deep Tibetan/East Asian pass."""
import json, os
OUT = os.path.join(os.path.dirname(__file__), '..')
def W(name, obj):
    json.dump(obj, open(os.path.join(OUT, name), 'w'), ensure_ascii=False, indent=1)
    print(name, len(obj) if hasattr(obj, '__len__') else '')

